def solve(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    # noise color: most common non-bg
    rest=[(v,c) for v,c in cnt.items() if v!=bg]
    rest.sort(key=lambda x:-x[1])
    noise=rest[0][0]
    # cluster: connected comp of non-bg, non-noise, size>2
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (bg,noise) and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx] not in (bg,noise) and (ny,nx) not in seen:
                                st.append((ny,nx))
                comps.append(comp)
    comp=max(comps,key=len)
    rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    tile=[[g[r][c] if (r,c) in set(comp) else bg for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    th,tw=len(tile),len(tile[0]); cy,cx=(th-1)//2,(tw-1)//2
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==noise:
                for i in range(th):
                    for j in range(tw):
                        if tile[i][j]!=bg:
                            y,x=r+i-cy,c+j-cx
                            if 0<=y<h and 0<=x<w: out[y][x]=tile[i][j]
    return out
